// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY, LogFile} from "../src/PENNY_BY_PENNY.sol";

// This test deploys a recording LogFile replacement so we can observe when Collect causes
// the contract to emit a Log.AddMessage for a Collect and thereby infer that a payment
// and balance decrease happened. The reference implementation requires acc.balance >= MinSum
// before permitting Collect; the mutant removes that guard. We fuzz caller, initial deposit,
// collect amount, lockTime, and MinSum so the fuzzer can find inputs where balance < MinSum
// but Collect still succeeds on the mutant and the recorder observes the Collect event.

contract InvMutTest is Test {
    PENNY_BY_PENNY c;
    RecorderLog rec;

    function setUp() public {
        c = new PENNY_BY_PENNY();
        rec = new RecorderLog();
        // Set the LogFile to our recorder and set MinSum via SetMinSum.
        // Note: both SetLogFile and SetMinSum are guarded by intitalized flag, so call them before Initialized().
        c.SetLogFile(address(rec));
    }

    // fuzz params: actor (caller who will Put and Collect), initial deposit, lockTime, collect amount, minSum
    function testFuzz_property(address actor, uint128 deposit, uint32 lockTime, uint128 collectAmt, uint128 minSum) public {
        // Keep domain wide but avoid trivial zero-address actor
        vm.assume(actor != address(0));
        // bound fuzzed amounts to reasonable ranges to avoid overflow/time issues
        uint256 dep = bound(deposit, 0, 1 ether);
        uint256 amt = bound(collectAmt, 0, 1 ether);
        uint256 ms = uint256(minSum);
        // choose lockTime small enough not to overflow when added to block.timestamp
        uint256 lt = uint256(lockTime);

        // Fund actor so they can send deposit and possibly collect
        vm.deal(actor, 2 ether);

        // Set MinSum on c (guarded by intitalized flag, so we must set before Initialized)
        c.SetMinSum(ms);

        // Now mark contract initialized so further Set* calls revert (mirrors typical setup)
        c.Initialized();

        // Actor performs Put to credit their account with dep and set unlockTime to now+lt if larger
        vm.prank(actor);
        c.Put{value: dep}(lt);

        // Fast-forward time to ensure block.timestamp > unlockTime (so unlock condition satisfied)
        vm.warp(block.timestamp + lt + 1);

        // Clear recorder's state before Collect
        rec.clear();

        // Attempt Collect from actor for amount amt, capturing whether the external call succeeded by observing recorder
        vm.prank(actor);
        // call Collect; it does an external call to Log.AddMessage which Recorder will record when Collect proceeds
        try c.Collect(amt) {
            // call succeeded (Collect didn't revert). We still rely on Recorder to tell if a Collect happened
        } catch {
            // if Collect reverted, no transfer / Log.AddMessage occurred
        }

        // Now inspect recorder: if it recorded a Collect entry, that means the contract performed the external Log.AddMessage
        // on Collect. For the correct contract, that must only happen when pre-call balance >= MinSum.
        // We need to assert the universal property: if pre-call balance < MinSum then recorder must NOT have observed a Collect.
        // But we cannot read pre-call balance after the fact; we reconstructed pre-call balance as 'dep' (no other actor touched it).
        // So we assert: if dep < ms then recorder must not have recorded a Collect entry for actor with val == amt.

        if (dep < ms) {
            // If the recorder has any Collect record matching this actor and amt, the mutant would allow it and fail this assertion.
            // The recorder stores the last recorded call data and a count; we check that no Collect with these params was observed.
            bool seen = rec.seenCollectFrom(actor, amt);
            assertTrue(!seen);
        } else {
            // when dep >= ms both reference and mutant may allow Collect (depending on unlock etc). We make no assertion in that case.
            assertTrue(true);
        }
    }
}

// Minimal Recorder that mimics LogFile.AddMessage signature and records calls
contract RecorderLog {
    struct Entry { address sender; uint val; string data; }
    Entry[] public history;

    // match signature AddMessage(address,uint256,string)
    function AddMessage(address _adr, uint _val, string memory _data) public {
        history.push(Entry({sender: _adr, val: _val, data: _data}));
    }

    function clear() public {
        delete history;
    }

    // helper read by test
    function seenCollectFrom(address who, uint val) public view returns (bool) {
        for (uint i = 0; i < history.length; i++) {
            if (history[i].sender == who && history[i].val == val) return true;
        }
        return false;
    }
}
